const { inspect } = require('node:util');

class ShoppingCart {
  constructor() {
    this.items = [];
    this.discount = 0;
  }

  /**
   * Adds an item, or increases the quantity of an item already in the cart.
   * @throws {TypeError} name is not a non-empty string, price is not a finite
   *   number, or quantity is not an integer.
   * @throws {RangeError} price is negative or quantity is below 1.
   */
  addItem(name, price, quantity) {
    if (typeof name !== 'string' || name.trim() === '') {
      throw new TypeError(`Item name must be a non-empty string, received ${inspect(name)}`);
    }
    if (!Number.isFinite(price)) {
      throw new TypeError(`Price of ${inspect(name)} must be a finite number, received ${inspect(price)}`);
    }
    if (price < 0) {
      throw new RangeError(`Price of ${inspect(name)} must not be negative, received ${price}`);
    }
    if (!Number.isInteger(quantity)) {
      throw new TypeError(`Quantity of ${inspect(name)} must be an integer, received ${inspect(quantity)}`);
    }
    if (quantity < 1) {
      throw new RangeError(`Quantity of ${inspect(name)} must be at least 1, received ${quantity}`);
    }

    const existing = this.items.find(i => i.name === name);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.push({ name, price, quantity });
    }
  }

  /**
   * @throws {Error} the item is not in the cart.
   */
  removeItem(name) {
    if (!this.items.some(i => i.name === name)) {
      throw new Error(`Cannot remove ${inspect(name)}: item is not in the cart`);
    }
    this.items = this.items.filter(i => i.name !== name);
  }

  getTotal() {
    let total = 0;
    for (let i = 0; i < this.items.length; i++) {
      total += this.items[i].price * this.items[i].quantity;
    }
    // Scaling by the remaining fraction keeps 100% off at exactly 0; subtracting
    // total * discount / 100 can leave a negative float residue.
    return total * (1 - this.discount / 100);
  }

  /**
   * Sets the discount percentage, replacing any previous discount.
   * @throws {TypeError} percent is not a finite number.
   * @throws {RangeError} percent is outside 0–100.
   */
  applyDiscount(percent) {
    if (!Number.isFinite(percent)) {
      throw new TypeError(`Discount must be a finite number, received ${inspect(percent)}`);
    }
    if (percent < 0 || percent > 100) {
      throw new RangeError(`Discount must be between 0 and 100, received ${percent}`);
    }
    this.discount = percent;
  }

  getItemCount() {
    return this.items.length;
  }
}

module.exports = ShoppingCart;

