      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects a quantity that is not an integer', () => {
      for (const quantity of [1.5, NaN, '2', null, undefined]) {
        assert.throws(() => cart.addItem('apple', 1, quantity), { name: 'TypeError', message: /quantity/i }, `quantity ${inspect(quantity)}`);
      }
      assert.equal(cart.getItemCount(), 0);
    });

    it('rejects an empty, whitespace-only or non-string name', () => {
      for (const name of ['', '   ', null, undefined, 42, Object.create(null)]) {
        assert.throws(() => cart.addItem(name, 1, 1), { name: 'TypeError', message: /name/i }, `name ${inspect(name)}`);
      }
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('removeItem', () => {
    // Bug 2: `i.name = name` assigned instead of compared, so nothing was
    // removed and every remaining item was renamed.
    it('removes only the named item and leaves the others untouched', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);

      cart.removeItem('banana');

      assert.deepEqual(cart.items, [
        { name: 'apple', price: 1, quantity: 1 },
        { name: 'cherry', price: 3, quantity: 1 },
      ]);
    });

    it('excludes the removed item from the total', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);

      cart.removeItem('apple');

      assert.equal(cart.getTotal(), 2);
    });

    // Bug 2: a missing item was silently ignored.
    it('throws when the item is not in the cart and leaves the cart unchanged', () => {
      cart.addItem('apple', 1, 1);

      assert.throws(() => cart.removeItem('pear'), { message: /'pear'.*not in the cart/ });
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 1 }]);
    });

    it('throws when removing from an empty cart', () => {
      assert.throws(() => cart.removeItem('apple'), /not in the cart/);
    });
  });

  describe('getTotal', () => {
    // Bug 3: `i <= length` read past the end of the array and threw.
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('sums price times quantity across all items without a discount', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('banana', 0.25, 4);
      cart.addItem('cherry', 10, 1);

      assert.equal(cart.getTotal(), 14);
    });

    // Bug 4: the discount was added to the total instead of subtracted.
    it('subtracts the discount percentage from the total', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(10);

      assert.equal(cart.getTotal(), 90);
    });

    it('returns exactly 0 with a 100% discount even when the subtotal carries float error', () => {
      cart.addItem('gum', 0.07, 3); // 0.07 * 3 === 0.21000000000000002
      cart.applyDiscount(100);

      assert.equal(cart.getTotal(), 0);
    });

    it('applies the discount to items added after it', () => {
      cart.applyDiscount(25);
      cart.addItem('apple', 20, 2);

      assert.equal(cart.getTotal(), 30);
    });
  });

  describe('applyDiscount', () => {
    it('accepts the 0 and 100 boundaries and fractional percentages', () => {
      cart.addItem('apple', 200, 1);

      for (const [percent, expected] of [[0, 200], [100, 0], [12.5, 175]]) {
        cart.applyDiscount(percent);
        assert.equal(cart.getTotal(), expected, `discount ${percent}%`);
      }
    });

    it('replaces the previous discount rather than stacking', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(20);
      cart.applyDiscount(10);

      assert.equal(cart.getTotal(), 90);
    });

    // Bug 5: out-of-range discounts were accepted.
    it('rejects discounts above 100 or below 0 and keeps the previous discount', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);

      for (const percent of [100.01, 150, -0.01, -10]) {
        assert.throws(() => cart.applyDiscount(percent), { name: 'RangeError', message: /between 0 and 100/ }, `discount ${percent}`);
      }
      assert.equal(cart.getTotal(), 90);
    });

    it('rejects a discount that is not a finite number', () => {
      cart.addItem('apple', 100, 1);

      for (const percent of [NaN, Infinity, '10', null, undefined]) {
        assert.throws(() => cart.applyDiscount(percent), { name: 'TypeError', message: /discount/i }, `discount ${inspect(percent)}`);
      }
      assert.equal(cart.getTotal(), 100);
    });
  });

  describe('getItemCount', () => {
    it('counts distinct items, not total quantity', () => {
      assert.equal(cart.getItemCount(), 0);

      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 1);
      assert.equal(cart.getItemCount(), 2);

      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });
  });
});
